-- Gerado por scripts/insert_natal_deco.mjs — "Casinha Lanterna" (rascunho, família Decoração)
insert into prod_designs (id, nome, descricao, familia, estado, acesso_maker, disponivel_consumidor, capa_familia, usa_modo, tags, preco_creditos, scad_template, generation_schema, parametros_default)
values ('casinha', 'Casinha Lanterna', 'Casinha oca com janelas, porta e chaminé, aberta em baixo para pôr por cima de uma vela LED. Faz uma aldeia de Natal com várias medidas.', 'Decoração', 'rascunho', 'gratuito', false, false, false,
  array['casinha', 'casa', 'lanterna', 'LED', 'natal', 'aldeia'], 1, $tpl$// Casinha Lanterna — o modelo está em templates/decoracao/partes/casinha.scad (backend)
include </app/templates/decoracao/casinha.scad>
$tpl$, '{"engine":"openscad","version":1,"parameters":{"deco":{"order":0,"default":"casinha","ui":{"widget":"hidden"}},"largura":{"order":1,"type":"number","min":40,"max":160,"unit":"mm","default":60,"ui":{"label":"Largura (frente)","widget":"slider","step":1}},"profundidade":{"order":2,"type":"number","min":30,"max":160,"unit":"mm","default":50,"ui":{"label":"Profundidade","widget":"slider","step":1}},"altura":{"order":3,"type":"number","min":25,"max":160,"unit":"mm","default":50,"ui":{"label":"Altura das paredes","widget":"slider","step":1}},"inclinacao":{"order":4,"type":"number","min":40,"max":60,"unit":"°","default":45,"ui":{"label":"Inclinação do telhado","widget":"slider","step":1}},"janelas":{"order":5,"type":"number","min":0,"max":4,"default":2,"ui":{"label":"Janelas atrás e em cada lado","widget":"slider","step":1}},"chamine":{"order":6,"type":"boolean","default":true,"ui":{"label":"Chaminé","widget":"checkbox"}},"parede":{"order":7,"type":"number","min":1.2,"max":4,"unit":"mm","default":2,"ui":{"label":"Espessura das paredes","widget":"slider","step":0.1}},"info_casinha":{"order":99,"default":null,"ui":{"widget":"info","text":"🏠 Aberta em baixo: põe-na por cima de uma vela LED. Imprime de pé, sem suportes. Em branco ou bege a luz passa pelas paredes; em cores escuras só se vê pelas janelas. Recomendamos velas LED (as cavidades são para velas de chá LED, 38 × 16 mm, com folga). Nunca uses velas a sério: o plástico amolece e arde."}}}}'::jsonb, '{}'::jsonb)
on conflict (id) do update set nome = excluded.nome, descricao = excluded.descricao, tags = excluded.tags,
  scad_template = excluded.scad_template, generation_schema = excluded.generation_schema;
